style.css:
/* Deep Current — Global Theme */
/* i really want this to be global */

/* Change these values to customize the theme */
:root {
  --my-primary: #116EA1;
  --my-primary-hover: #0D5A85;
  --my-primary-soft: #E8F3F9;
  --my-text: #263746;
  --my-background: #F7FAFC;
  --my-border: #DCE5EB;
}

/* Clean typography and page background */
body {
  background-color: var(--my-background) !important;
  color: var(--my-text) !important;
  font-family: "Segoe UI", Arial, sans-serif !important;
}

/* Links */
a {
  color: var(--my-primary) !important;
}

a:hover {
  color: var(--my-primary-hover) !important;
}

/* Buttons and primary actions */
button,
input[type="button"],
input[type="submit"],
[role="button"] {
  border-radius: 6px !important;
}

button:not(:disabled),
input[type="button"],
input[type="submit"],
[role="button"] {
  transition: background-color 0.2s ease, border-color 0.2s ease !important;
}

/* Form controls */
input,
select,
textarea {
  border-color: var(--my-border) !important;
  border-radius: 5px !important;
}

input:focus,
select:focus,
textarea:focus {
  border-color: var(--my-primary) !important;
  outline-color: var(--my-primary) !important;
}

/* Text selection */
::selection {
  background: var(--my-primary) !important;
  color: white !important;
}

/* Scrollbars */
* {
  scrollbar-color: var(--my-primary) var(--my-background) !important;
}
